<template>
 <view class="wizard">
  <view class="wizard-top"><text class="wizard-title">发布本局招募</text><text class="draft-status">{{saveFailed?'草稿保存失败':'自动保存草稿'}}</text></view>
  <view class="steps" role="navigation" aria-label="发布步骤"><view class="step-rail"><view class="step-progress" :style="{width:((step-1)/3*100)+'%'}"/></view>
   <button v-for="(name,index) in stepNames" :key="name" :class="{active:step===index+1,done:step>index+1}" :aria-current="step===index+1?'step':undefined" @click="go(index+1)"><text class="step-no">{{index+1}}</text><text>{{name}}</text></button>
  </view>
  <view v-if="saveFailed" class="draft-warning" role="status"><text>{{saveIssue}}</text><button @click="saveDraft">重试保存</button></view>
  <view v-if="step===1" class="wizard-panel">
   <view class="section-heading">合作目的<text>选择这局主要做什么</text></view>
   <view class="purpose-grid"><button v-for="g in GOALS" :key="g" :class="{chosen:form.goal===g}" :aria-pressed="form.goal===g" @click="form.goal=g"><b>{{g}}</b><text>{{goalNotes[g]}}</text></button></view>
   <view v-if="errors.goal" class="error-line">{{errors.goal}}</view>
   <view v-if="form.goal==='33任务'" class="section-block"><view class="subheading">33任务 <text>可多选</text></view><view v-for="group in TASK_GROUPS" :key="group.label" class="task-group"><text class="muted-label">{{group.label}}</text><view class="chips"><button v-for="task in group.values" :key="task" :class="{chosen:form.tasks.includes(task)}" :aria-pressed="form.tasks.includes(task)" @click="toggleTask(task)">{{form.tasks.includes(task)?'✓ ':''}}{{task}}</button></view></view><view v-if="errors.tasks" class="error-line">{{errors.tasks}}</view></view>
  </view>
  <view v-if="step===2" class="wizard-panel">
   <view class="section-heading">地图与难度<text>可添加多张地图，每张选择一个难度</text></view>
   <view class="map-choices"><button v-for="map in Object.keys(MAP_MODES)" :key="map" :class="{chosen:hasMap(map)}" :aria-pressed="hasMap(map)" @click="addMap(map)">{{hasMap(map)?'✓':'＋'}} {{map}}</button></view>
   <view v-for="pair in form.maps" :key="pair.map" class="map-pair"><view class="pair-head"><b>{{pair.map}}</b><button :aria-label="'移除'+pair.map" class="remove-map" @click="form.maps=form.maps.filter(m=>m.map!==pair.map)">×</button></view><view class="chips"><button v-for="mode in MAP_MODES[pair.map]" :key="mode" :class="{chosen:pair.difficulty===mode,night:mode==='机密·黑夜'}" :aria-pressed="pair.difficulty===mode" @click="pair.difficulty=mode">{{mode}}</button></view></view>
   <view v-if="!form.maps.length" class="empty-map">从上方选择本次可以玩的地图</view>
   <view v-if="errors.maps" class="error-line">{{errors.maps}}</view>
  </view>
  <view v-if="step===3" class="wizard-panel">
   <view class="section-heading">自身配置<text>填写这局实际带入的配置</text></view>
   <view v-if="needsGear" class="gear-list"><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{gear.label}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form[gear.key]===n}" :aria-pressed="form[gear.key]===n" @click="form[gear.key]=n">{{n}}<text>级</text></button></view><view v-if="errors[gear.key]" class="error-line row-error">{{errors[gear.key]}}</view></view></view>
   <view class="subheading" :class="{'section-block':needsGear}">我的打法风格</view><view class="style-group"><button v-for="(name,i) in STYLE_LABELS" :key="name" :class="{chosen:form.style===i+1}" :aria-pressed="form.style===i+1" @click="form.style=i+1">{{i+1}} {{name}}</button></view>
   <view class="section-block"><view class="subheading">硬核实力</view><view class="guidance">请按真实数据填写，实力差距过大会影响双方体验</view><view class="chips score-modes"><button :class="{chosen:form.score_mode==='auto'}" @click="form.score_mode='auto'">自动计算</button><button :class="{chosen:form.score_mode==='manual'}" @click="form.score_mode='manual'">手动填写</button></view>
    <view v-if="form.score_mode==='auto'" class="stats-grid"><label v-for="field in scoreFields" :key="field.key" :class="{invalid:errors[field.key]}"><view class="field-label">{{field.label}}<text class="required">*</text><text v-if="empty(form[field.key])" class="missing">待填写</text></view><input v-model.number="form[field.key]" type="digit" :placeholder="field.placeholder" placeholder-style="color:#718096" @blur="checkField(field.key)"/><text v-if="errors[field.key]" class="error-line">{{errors[field.key]}}</text></label></view>
    <label v-else :class="{invalid:errors.manual_score}"><view class="field-label">我的实力分 <text class="required">*</text></view><input v-model.number="form.manual_score" type="digit" placeholder="输入实力分" placeholder-style="color:#718096" @blur="checkField('manual_score')"/><text v-if="errors.manual_score" class="error-line">{{errors.manual_score}}</text></label>
    <strength-score :value="myScore"/>
   </view>
  </view>
  <view v-show="step===4" class="wizard-panel">
   <view class="section-heading">队友要求<text>同时满足彼此要求才会匹配</text></view>
   <view class="subheading">可接受的打法范围</view><view class="range-grid"><view><text class="muted-label">最低</text><view class="level-group"><button v-for="n in 5" :key="n" :class="{chosen:form.partner_style_min===n}" @click="form.partner_style_min=n">{{n}}</button></view></view><view><text class="muted-label">最高</text><view class="level-group"><button v-for="n in 5" :key="n" :class="{chosen:form.partner_style_max===n}" @click="form.partner_style_max=n">{{n}}</button></view></view></view><view class="small-note">1 很保守 — 5 很激进</view><view v-if="errors.partner_style" class="error-line">{{errors.partner_style}}</view>
   <view v-if="needsGear" class="section-block"><view class="subheading">队友最低装备<text>不高于自己的对应装备</text></view><view v-for="gear in GEAR_FIELDS" :key="gear.key" class="choice-row"><text class="row-label">{{gear.label}}</text><view class="level-group"><button v-for="n in 6" :key="n" :class="{chosen:form['partner_'+gear.key+'_min']===n}" :disabled="n>form[gear.key]" @click="form['partner_'+gear.key+'_min']=n">{{n}}<text>级</text></button></view><view v-if="errors['partner_'+gear.key+'_min']" class="error-line row-error">{{errors['partner_'+gear.key+'_min']}}</view></view></view>
   <view class="section-block"><view class="subheading">队友实力范围<text v-if="form.strength_range_mode==='auto'">默认 ±30%</text></view><view class="range-summary"><text>{{range[0]}} — {{range[1]}} 分</text><button @click="toggleRange">{{form.strength_range_mode==='auto'?'调整范围':'恢复默认'}}</button></view><view v-if="form.strength_range_mode==='custom'" class="range-grid"><label>最低实力分<input v-model.number="form.strength_min" type="digit" placeholder="最低接受多少分" placeholder-style="color:#718096"/></label><label>最高实力分<input v-model.number="form.strength_max" type="digit" placeholder="最高接受多少分" placeholder-style="color:#718096"/></label></view><view v-if="errors.strength_range" class="error-line">{{errors.strength_range}}</view></view>
   <view class="section-block"><view class="subheading">基础信息</view><phone-login :profile="personalProfile" @restore="restoreProfile"/><view class="basic-grid"><label :class="{invalid:errors.nickname}"><view class="field-label">队内昵称 <text class="required">*</text></view><input v-model="form.nickname" maxlength="24" placeholder="怎么称呼你" placeholder-style="color:#718096"/><text v-if="errors.nickname" class="error-line">{{errors.nickname}}</text></label><view v-for="field in baseFields" :key="field.key" class="basic-field">{{field.label}}<dark-select v-model="form[field.key]" :options="field.values" :label="field.label" :option-labels="field.labels||{}"/></view></view></view>
   <view class="section-block"><view class="subheading">招募方式</view><view class="chips"><button :class="{chosen:form.discovery==='browse'}" @click="form.discovery='browse'">自己挑选</button><button :class="{chosen:form.discovery==='auto'}" @click="form.discovery='auto'">自动匹配</button></view><view class="public-row"><text>在大厅公开招募</text><switch :checked="form.public" color="#9bcf65" @change="form.public=$event.detail.value"/></view></view>
  </view>
  <view v-if="preview" class="publish-overlay" @click.self="closePreview"><view class="publish-dialog" role="dialog" aria-modal="true" aria-label="发布前确认" tabindex="-1" @keydown.esc.stop="closePreview" @keydown.tab="trapPreviewFocus">
   <view class="publish-head"><view><b>发布前确认</b><text>确认招募条件，发布后即可寻找队友</text></view><button class="preview-close" tabindex="0" aria-label="关闭招募预览" :disabled="busy" @click="closePreview">×</button></view>
   <view class="publish-content">
    <view class="preview-tags"><text class="purpose-tag">{{form.goal}}</text><text v-for="m in form.maps" :key="m.map">{{m.map}} · {{m.difficulty}}</text></view>
    <view v-if="form.goal==='33任务'" class="preview-line"><text class="preview-key">任务</text><view class="preview-tags"><text v-for="task in form.tasks" :key="task">{{task}}</text></view></view>
    <view class="preview-comparison"><view class="preview-column"><view class="preview-column-title">我的配置</view><view v-if="needsGear" class="preview-metric"><text>装备</text><b>头{{form.helmet}} · 甲{{form.armor}} · 弹{{form.ammo}}</b></view><view class="preview-metric"><text>打法</text><b>{{form.style}} · {{STYLE_LABELS[form.style-1]}}</b></view><view class="preview-metric"><text>实力</text><b>{{myScore}} 分</b></view></view><view class="preview-column"><view class="preview-column-title">队友要求</view><view v-if="needsGear" class="preview-metric"><text>装备</text><b>头≥{{form.partner_helmet_min}} · 甲≥{{form.partner_armor_min}} · 弹≥{{form.partner_ammo_min}}</b></view><view class="preview-metric"><text>打法</text><b>{{form.partner_style_min}}–{{form.partner_style_max}} 档</b></view><view class="preview-metric"><text>实力</text><b>{{range[0]}}–{{range[1]}} 分</b></view></view></view>
    <view class="preview-details"><text>{{form.nickname}}</text><text>{{form.region}}</text><text>{{{PC:'电脑端',Console:'主机端',Mobile:'手机端'}[form.platform]}}</text><text>{{form.language}}</text><text>{{form.voice}}</text><text>{{form.slot}}</text><text>{{form.discovery==='auto'?'自动匹配':'自己挑选'}}</text><text>{{form.public?'公开招募':'不公开招募'}}</text></view>
    <view v-if="submitError" class="preview-submit-error" role="alert">{{submitError}}</view>
   </view>
   <view class="publish-footer"><button tabindex="0" :disabled="busy" @click="closePreview">返回修改</button><button tabindex="0" class="publish-confirm" :disabled="busy||activeTicket" @click="finish">{{busy?'发布中…':'确认发布'}}</button></view>
  </view></view>
  <view class="wizard-actions"><button class="save-draft" @click="saveDraft">{{saved?'✓ 已保存到本地':'保存到本地'}}</button><view class="nav-buttons"><button v-if="step>1" @click="go(step-1)">上一步</button><button v-if="step<4" class="primary" @click="next">下一步</button><button v-else class="primary" :disabled="busy||activeTicket" @click="finish">{{activeTicket?'已有进行中的组局':busy?'发布中…':'预览招募'}}</button></view></view>
 </view>
</template>
<script setup>
import {computed,reactive,ref,watch,nextTick,onBeforeUnmount} from 'vue'
import DarkSelect from './dark-select.vue'
import StrengthScore from './strength-score.vue'
import PhoneLogin from './phone-login.vue'
import {MAP_MODES,GOALS,TASK_GROUPS,STYLE_LABELS,GEAR_FIELDS,scoreOf,strengthRange} from '../utils/recruitment-options.js'
import {loadPreferences,savePreferencesDetailed,pickPreferences} from '../utils/pilot-preferences.js'
import {stepErrors} from '../utils/recruitment-validation.js'
const props=defineProps({busy:Boolean,activeTicket:Boolean,submitError:String,importProfile:Object})
const emit=defineEmits(['submit','clear-error'])
const loaded=loadPreferences(uni)
const form=reactive(loaded.values),step=ref(form.wizard_step),errors=ref({}),saveFailed=ref(false),saveIssue=ref(''),saved=ref(false),preview=ref(false)
let lastSaveError=''
watch(()=>props.importProfile,value=>{if(!value)return;Object.assign(form,pickPreferences({...value,wizard_step:1}));step.value=1;errors.value={};preview.value=false;persistDraft()},{immediate:true})
function persistDraft(){const result=savePreferencesDetailed(uni,form);saveFailed.value=!result.ok;saveIssue.value=result.message||'';const diagnostic=result.ok?'':result.stage+':'+result.errorName+':'+result.reason;if(diagnostic&&diagnostic!==lastSaveError)console.warn('[draft-save]',diagnostic);lastSaveError=diagnostic;return result.ok}
const stepNames=['合作目的','地图与难度','自身配置','队友要求']
const goalNotes={'33任务':'完成保险箱相关任务','卡战备跑刀':'轻装搜集','搜打撤':'搜集物资，择机交战','猛攻':'主动寻找交战'}
const scoreFields=[{key:'confidential_kd',label:'机密 KD',placeholder:'例如 1.5'},{key:'top_secret_kd',label:'绝密 KD',placeholder:'例如 2.0'},{key:'combat_score',label:'战斗分',placeholder:'例如 50'}]
const baseFields=[{key:'region',label:'区服',values:['NA','EU','SEA','OCE','ME']},{key:'platform',label:'游戏端',values:['PC','Console','Mobile'],labels:{PC:'电脑端',Console:'主机端',Mobile:'手机端'}},{key:'language',label:'沟通语言',values:['中文','English','日本語']},{key:'voice',label:'语音方式',values:['开麦','听指挥与标记']},{key:'slot',label:'开局时段',values:['现在起一小时','今天晚间']}]
const personalKeys=['nickname','region','platform','language','voice','slot','helmet','armor','ammo','style','score_mode','manual_score','confidential_kd','top_secret_kd','combat_score']
const personalProfile=computed(()=>Object.fromEntries(personalKeys.map(k=>[k,form[k]])))
function restoreProfile(values){for(const key of personalKeys)if(Object.prototype.hasOwnProperty.call(values,key))form[key]=values[key]??(['helmet','armor','ammo'].includes(key)?null:'')}
const needsGear=computed(()=>form.goal!=='卡战备跑刀'),myScore=computed(()=>scoreOf(form)),range=computed(()=>strengthRange(form))
const empty=n=>n===''||n==null
watch(form,()=>{saved.value=false;preview.value=false;persistDraft();if(Object.keys(errors.value).length)errors.value=stepErrors(form,step.value)},{deep:true,flush:'post'})
for(const gear of GEAR_FIELDS)watch(()=>form[gear.key],n=>{const k='partner_'+gear.key+'_min';if(n!=null&&form[k]>n)form[k]=null})
defineExpose({getDraft:()=>JSON.parse(JSON.stringify(form))})
function saveDraft(){saved.value=persistDraft()}
function toggleTask(task){form.tasks=form.tasks.includes(task)?form.tasks.filter(t=>t!==task):[...form.tasks,task]}
function hasMap(map){return form.maps.some(m=>m.map===map)}
function addMap(map){if(!hasMap(map))form.maps.push({map,difficulty:''})}
function scrollTop(){uni.pageScrollTo({scrollTop:0,duration:200})}
function go(n){if(n>step.value){for(let i=1;i<n;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;scrollTop();return}}}step.value=n;form.wizard_step=n;errors.value={};preview.value=false;scrollTop()}
function next(){go(step.value+1)}
function checkField(key){const found=stepErrors(form,step.value);if(found[key])errors.value={...errors.value,[key]:found[key]}}
function toggleRange(){if(form.strength_range_mode==='auto'){const [lo,hi]=range.value;form.strength_min=lo;form.strength_max=hi;form.strength_range_mode='custom'}else form.strength_range_mode='auto'}
let oldBodyOverflow='',oldRootOverflow='',locked=false,previousFocus=null
function closePreview(){if(!props.busy)preview.value=false}
function unlockPreview(){if(!locked||typeof document==='undefined')return;document.body.style.overflow=oldBodyOverflow;document.documentElement.style.overflow=oldRootOverflow;locked=false;previousFocus?.focus?.()}
watch(preview,async shown=>{
 if(typeof document==='undefined')return
 if(shown){oldBodyOverflow=document.body.style.overflow;oldRootOverflow=document.documentElement.style.overflow;previousFocus=document.activeElement;document.body.style.overflow='hidden';document.documentElement.style.overflow='hidden';locked=true;await nextTick();document.querySelector('.publish-dialog')?.focus()}
 else unlockPreview()
})
function trapPreviewFocus(event){if(typeof document==='undefined')return;const elements=[...document.querySelectorAll('.publish-dialog [tabindex="0"]')].filter(el=>!el.hasAttribute('disabled'));if(!elements.length)return;const first=elements[0],last=elements[elements.length-1];if(event.shiftKey&&(document.activeElement===first||document.activeElement===document.querySelector('.publish-dialog'))){event.preventDefault();last.focus()}else if(!event.shiftKey&&document.activeElement===last){event.preventDefault();first.focus()}}
onBeforeUnmount(unlockPreview)
function finish(){for(let i=1;i<=4;i++){const found=stepErrors(form,i);if(Object.keys(found).length){step.value=i;form.wizard_step=i;errors.value=found;preview.value=false;scrollTop();return}}if(!preview.value){emit('clear-error');preview.value=true;return}if(props.busy||props.activeTicket)return;const payload=JSON.parse(JSON.stringify(form));delete payload.wizard_step;for(const key of ['manual_score','confidential_kd','top_secret_kd','combat_score','strength_min','strength_max'])if(payload[key]==='')payload[key]=null;if(payload.score_mode==='manual')for(const key of ['confidential_kd','top_secret_kd','combat_score'])payload[key]=null;else payload.manual_score=null;if(!needsGear.value)for(const g of GEAR_FIELDS){payload[g.key]=null;payload['partner_'+g.key+'_min']=null}if(form.goal!=='33任务')payload.tasks=[];emit('submit',payload)}
</script>
<style scoped>
